        if (isBusinessDay(date) && (zdt.getHour() < 16 || (zdt.getHour() == 16 && zdt.getMinute() == 0 && zdt.getSecond() == 0))) {
            return date.format(DATE_FORMATTER);
        }
        return nextBusinessDay(date).format(DATE_FORMATTER);
    }

    @Override
    public String settlementDate(String submittedAt) {
        return nextBusinessDay(LocalDate.parse(processingDate(submittedAt), DATE_FORMATTER)).format(DATE_FORMATTER);
    }

