        LocalDate due = parseDate(dueDate);
        ZonedDateTime paid = ZonedDateTime.parse(paidAt, INSTANT_FORMATTER).withZoneSameInstant(WARSAW);
        long days = ChronoUnit.DAYS.between(due, paid.toLocalDate());
        return (int) Math.max(0, days);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate start = parseDate(date);
        LocalDate end = start.plusMonths(months);
        if (start.getDayOfMonth() == start.lengthOfMonth()) {
            end = end.withDayOfMonth(end.lengthOfMonth());
        }
        return end.format(DATE_FORMATTER);
    }

    private LocalDate parseDate(String date) {
        try {
            return LocalDate.parse(date, DATE_FORMATTER);
        } catch (DateTimeParseException | NullPointerException e) {
            throw new IllegalArgumentException("Invalid date");
        }
    }

    private boolean isBusinessDay(LocalDate date) {
        return date.getDayOfWeek() != DayOfWeek.SATURDAY && 
               date.getDayOfWeek() != DayOfWeek.SUNDAY &&
               !HOLIDAYS.contains(String.format("%02d-%02d", date.getMonthValue(), date.getDayOfMonth()));
    }

    private LocalDate nextBusinessDay(LocalDate date) {
        LocalDate next = date.plusDays(1);
        while (!isBusinessDay(next)) {
            next = next.plusDays(1);
        }
        return next;
    }
}
